def _workspace_truth_surface_name(*, session_scoped: bool) -> str:
    return "working" if session_scoped else "canonical"


def _workspace_truth_metadata(*, session_scoped: bool) -> dict[str, Any]:
    surface = _workspace_truth_surface_name(session_scoped=session_scoped)
    if session_scoped:
        return {
            "surface": surface,
            "committed": False,
            "live": False,
            "guidance": "This result comes from the active session workspace. Treat it as in-progress working state until a later commit/publish records canonical or live truth.",
        }
    return {
        "surface": surface,
        "committed": True,
        "live": False,
        "guidance": "This result comes from the committed canonical workspace hydrated from durable storage.",
    }


def _workspace_base_revision_state_path(workspace_root: Path) -> Path:
    return Path(workspace_root).expanduser().resolve() / ".takyon-workspace-base-revisions.json"


def _read_workspace_base_revisions(workspace_root: Path | None) -> dict[str, int]:
    if workspace_root is None:
        return {}
    path = _workspace_base_revision_state_path(workspace_root)
    if not path.exists():
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    if not isinstance(payload, dict):
        return {}
    revisions: dict[str, int] = {}
    for key, value in payload.items():
        normalized = _slugify(str(key or ""))
        if not normalized:
            continue
        try:
            revisions[normalized] = max(0, int(value or 0))
        except (TypeError, ValueError):
            continue
    return revisions


def _write_workspace_base_revisions(workspace_root: Path | None, revisions: Mapping[str, Any]) -> None:
    if workspace_root is None:
        return
    path = _workspace_base_revision_state_path(workspace_root)
    payload = {
        _slugify(str(key or "")): max(0, int(value or 0))
        for key, value in dict(revisions or {}).items()
        if _slugify(str(key or ""))
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    _atomic_write_text(path, _json_dumps(payload) + "\n")


def live_build_pointer(
    business: str,
    *,
    takyon_home: Path | str | None = None,
    database_url: str | None = None,
    timeout_ms: int = 2_000,
) -> str | None:
    """Resolve the intended live build pointer with one control-plane read.

    This is the narrow product-serving seam: one indexed SELECT against
    ``app_surface_contracts.live_build_id`` and nothing else. No summary read,
    no filesystem hydrate, no receipt scan, no workspace sync.
    """
    slug = _slugify(business)
    if not slug:
        return None
    store = TakyonStore(
        Path(takyon_home).expanduser() if takyon_home else get_takyon_home(),
        database_url=database_url,
        system_plane="product-serving",
    )
    with store._connect() as conn:
        try:
            bounded_timeout_ms = max(1, int(timeout_ms or 0))
        except (TypeError, ValueError):
            bounded_timeout_ms = 2_000
        try:
            conn.execute("SET LOCAL statement_timeout = ?", (bounded_timeout_ms,))
        except Exception:
            pass
        row = conn.execute(
            "SELECT live_build_id FROM app_surface_contracts WHERE business_slug = ?",
            (slug,),
        ).fetchone()
    if not row:
        return None
    return str(row.get("live_build_id") or "").strip().lower() or None


def _surface_live_publication_state(surface: dict[str, Any] | None, *, business: str) -> dict[str, Any]:
    payload = surface if isinstance(surface, dict) else {}
    build_id = str(payload.get("live_build_id") or "").strip()
    recorded_status = str(payload.get("publish_status") or "not_published").strip().lower() or "not_published"
    publish_target = str(
        payload.get("publish_target")
        or (_product_publish_target(business) if str(business or "").strip() else "")
    ).strip()
    recorded_public_url = str(payload.get("public_url") or "").strip()
    recorded_published_at = str(payload.get("published_at") or "").strip()
    publish_blocker = str(payload.get("publish_blocker") or "").strip()
    if build_id:
        publish_status = "published"
    elif recorded_status == "published":
        publish_status = "published"
    elif publish_blocker:
        publish_status = "blocked"
    else:
        publish_status = "not_published"
    return {
        "build_id": build_id,
        "publish_status": publish_status,
        "public_url": recorded_public_url or (publish_target if publish_status == "published" else ""),
        "published_at": recorded_published_at if publish_status == "published" else "",
        "probe": (
            str(payload.get("live_probe_status") or "unknown").strip().lower() or "unknown"
            if publish_status == "published"
            else "unknown"
        ),
        "probe_detail": str(payload.get("live_probe_detail") or "").strip() if publish_status == "published" else "",
        "publish_blocker": publish_blocker,
        "publish_target": publish_target,
    }


def _recorded_live_truth_metadata(surface: dict[str, Any] | None, *, business: str) -> dict[str, Any]:
    publication = _surface_live_publication_state(surface, business=business)
    return {
        "surface": "recorded_live",
        "committed": bool(publication.get("build_id")),
        "live": True,
        "build_id": str(publication.get("build_id") or ""),
        "publish_status": str(publication.get("publish_status") or "not_published"),
        "public_url": str(publication.get("public_url") or ""),
        "published_at": str(publication.get("published_at") or ""),
        "probe": str(publication.get("probe") or "unknown"),
        "probe_detail": str(publication.get("probe_detail") or ""),
        "guidance": "This is the recorded live/public state from the app surface contract and live build pointer. Probe status reports whether the public host matched that intended live build the last time publish checked it.",
    }


def _live_truth_snapshot(surface: dict[str, Any] | None, *, business: str) -> dict[str, Any]:
    truth = _recorded_live_truth_metadata(surface, business=business)
    if truth.get("build_id"):
        probe_status, probe_detail = _probe_product_public_url_status(str(truth.get("public_url") or ""))
        if probe_status:
            truth["probe"] = probe_status
        if probe_detail:
            truth["probe_detail"] = probe_detail
    return truth


def _business_file_truth_metadata(path: str, *, session_scoped: bool, revision: int = 0) -> dict[str, Any]:
    rel = _safe_relpath(path or ".", field="path").as_posix()
    workspace_truth = _workspace_truth_metadata(session_scoped=session_scoped)
    revision_payload = (
        {"base_revision": int(revision or 0)}
        if session_scoped
        else {"revision": int(revision or 0)}
    )
    if rel.startswith("metrics/receipts/"):
        return {
            "document_role": "receipt",
            "proof_level": "authoritative",
            "proof_guidance": "Machine-generated receipt. Use this as proof of the recorded operation or verified result.",
            "truth_surface": workspace_truth["surface"],
            "truth_guidance": workspace_truth["guidance"],
            **revision_payload,
        }
    if rel.startswith("product/site/"):
        return {
            "document_role": "implementation_source",
            "proof_level": "authoritative" if session_scoped else "mixed",
            "proof_guidance": (
                "Implementation source from the active session workspace. Use this to judge in-progress product edits."
                if session_scoped
                else "Implementation source from the committed canonical workspace. Use this for committed product source; cross-check live state separately."
            ),
            "truth_surface": workspace_truth["surface"],
            "truth_guidance": workspace_truth["guidance"],
            **revision_payload,
        }
    if rel.startswith("distribution/local-published/"):
        return {
            "document_role": "published_artifact",
            "proof_level": "authoritative",
            "proof_guidance": "Published outreach artifact. Use this as proof of a published outreach item.",
            "truth_surface": workspace_truth["surface"],
            "truth_guidance": workspace_truth["guidance"],
            **revision_payload,
        }
    if (
        rel in _COMMENTARY_BUSINESS_PATHS
        or rel.startswith("research/")
        or rel.startswith("distribution/campaign/")
    ):
        return {
            "document_role": "summary",
            "proof_level": "commentary",
            "proof_guidance": "Commentary and planning state only. Do not use this file by itself as proof that implementation, runtime wiring, or live behavior is present.",
            "truth_surface": workspace_truth["surface"],
            "truth_guidance": workspace_truth["guidance"],
            **revision_payload,
        }
    return {
        "document_role": "artifact",
        "proof_level": "mixed",
        "proof_guidance": "Business artifact. For implementation-state questions, cross-check with implementation source files or receipts.",
        "truth_surface": workspace_truth["surface"],
        "truth_guidance": workspace_truth["guidance"],
        **revision_payload,
    }

