def handle_business_request_app_magic_link(args: dict, **_: Any) -> str:
    store = _store()
    try:
        business = _slugify(str(args.get("business") or ""))
        email = _normalize_email(str(args.get("email") or ""))
        if _is_service_email(email):
            return tool_result({
                "success": True,
                "business": business,
                "email": email,
                "magic_link_id": "",
                "token": "",
                "verify_url": "",
                "expires_at": "",
                "email_sent": False,
                "email_requested": bool(args.get("send_email")),
                "provider_message_id": None,
                "external_side_effects": "none",
            })
        origin = str(args.get("origin") or "").rstrip("/")
        app_slug = _file_slug(str(args.get("app_slug") or business), business)
        send_email = bool(args.get("send_email"))
        with store._connect() as conn:
            business_row = store._ensure_business(conn, business)
            _enforce_business_work_focus(
                {"action": "app.customer.upsert", "business": business},
                str(business_row.get("work_focus") or "all"),
            )
            test_mode = _effective_business_mode(business_row.get("mode")) == "test"
            now = _now()
            link_id = ""
            expires_at = ""
            if isinstance(conn, _PGConn):
                leaves = store._app_leaves()
                with store._leaf_conn(conn) as leaf:
                    link_record, token = leaves["identity"].create_magic_link(
                        leaf,
                        business,
                        email,
                        purpose=str(args.get("purpose") or "login"),
                        name=args.get("name"),
                    )
                    app_user = leaves["identity"].get_app_user(
                        leaf,
                        business,
                        app_user_id=link_record.app_user_id,
                    )
                    leaves["profiles"].ensure_profile(
                        leaf,
                        business,
                        app_user_id=link_record.app_user_id,
                        display_name=None if app_user is None else app_user.name,
                    )
                if app_user is None:
                    raise TakyonError("app user is not active")
                if str(app_user.status or "active") != "active":
                    raise TakyonError("app user is not active")
                user = {
                    "id": app_user.id,
                    "email": app_user.email,
                    "status": app_user.status,
                }
                link_id = link_record.id
                expires_at = str(link_record.expires_at)
            else:
                user_id = uuid.uuid4().hex
                conn.execute(
                    "INSERT INTO app_users (id, business_slug, email, name, status, tier, metadata_json, created_at, updated_at) VALUES (?, ?, ?, ?, 'active', 'free', ?, ?, ?) "
                    "ON CONFLICT(business_slug, email) DO UPDATE SET "
                    "name = COALESCE(excluded.name, app_users.name), "
                    "updated_at = excluded.updated_at",
                    (user_id, business, email, args.get("name"), _json_dumps({"source": "magic_link"}), now, now),
                )
                user = store._row_to_dict(conn.execute("SELECT * FROM app_users WHERE business_slug = ? AND email = ?", (business, email)).fetchone())
                if str(user.get("status") or "active") != "active":
                    raise TakyonError("app user is not active")
                _ensure_sqlite_app_profile(
                    conn,
                    business,
                    str(user["id"]),
                    display_name=user.get("name"),
                )
                token = _random_token()
            link = f"{origin}/api/takyon/apps/{app_slug}/auth/verify?token={urllib.parse.quote(token)}" if origin else ""
            provider_message_id = None
            email_sent = False
            if send_email:
                if test_mode:
                    provider_message_id = f"test-mode-suppressed:{uuid.uuid4().hex}"
                else:
                    product_name = str(args.get("product_name") or business)
                    provider_message_id = _postmark_magic_link(email, product_name, link or token)
                    email_sent = True
            link_metadata = {
                "app_slug": app_slug,
                "email_requested": send_email,
                "email_sent": email_sent,
                "external_side_effects": "suppressed" if test_mode and send_email else "none" if not send_email else "sent",
            }
            if isinstance(conn, _PGConn):
                with store._leaf_conn(conn) as leaf:
                    leaf.execute(
                        "update app_magic_links set provider_message_id = %s, metadata = %s::jsonb where business_slug = %s and id = %s",
                        (provider_message_id, _json_dumps(link_metadata), business, link_id),
                    )
            else:
                link_id = uuid.uuid4().hex
                expires_at = _future(minutes=15)
                conn.execute(
                    "INSERT INTO app_magic_links (id, business_slug, app_user_id, email, token_hash, purpose, expires_at, provider_message_id, metadata_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (link_id, business, user["id"], email, _hash_token(token), str(args.get("purpose") or "login"), expires_at, provider_message_id, _json_dumps(link_metadata), now),
                )
            if test_mode and send_email:
                receipt_rel = f"metrics/receipts/app-magic-link/{link_id}.json"
                _atomic_write_text(store._business_root(business) / receipt_rel, _json_dumps({
                    "id": link_id,
                    "business": business,
                    "mode": "test",
                    "email": email,
                    "provider": "postmark",
                    "external_side_effects": "suppressed",
                    "sent": False,
                    "created_at": now,
                }) + "\n")
            store._record_event(conn, scope=f"business:{business}/app", business_slug=business, event_type="app.magic_link.request", payload={"email": email, "sent": email_sent, "requested_send": send_email, "provider_message_id": provider_message_id, "external_side_effects": "suppressed" if test_mode and send_email else "sent" if email_sent else "none"})
            store._rewrite_app_files(conn, business)
        return tool_result({"success": True, "business": business, "email": email, "magic_link_id": link_id, "token": token, "verify_url": link, "expires_at": expires_at, "email_sent": email_sent, "email_requested": send_email, "provider_message_id": provider_message_id, "external_side_effects": "suppressed" if test_mode and send_email else "sent" if email_sent else "none"})
    except Exception as exc:
        return tool_error(str(exc), success=False)


def handle_business_verify_app_magic_link(args: dict, **_: Any) -> str:
    store = _store()
    try:
        business = _slugify(str(args.get("business") or ""))
        token = str(args.get("token") or "").strip()
        if not token:
            raise TakyonError("token is required")
        with store._connect() as conn:
            business_row = store._ensure_business(conn, business)
            _enforce_business_work_focus(
                {"action": "app.customer.upsert", "business": business},
                str(business_row.get("work_focus") or "all"),
            )
            if isinstance(conn, _PGConn):
                link_target = store._row_to_dict(conn.execute(
                    "SELECT u.id, u.email, u.status FROM app_magic_links l "
                    "JOIN app_users u ON u.business_slug = l.business_slug AND u.id = l.app_user_id "
                    "WHERE l.business_slug = ? AND l.token_hash = ? AND l.used_at IS NULL AND l.expires_at > ? LIMIT 1",
                    (business, _hash_token(token), _now()),
                ).fetchone())
                if not link_target:
                    raise TakyonError("magic link is invalid, expired, or already used")
                if _app_user_is_service_identity(link_target):
                    raise TakyonError("magic link is invalid, expired, or already used")
                leaves = store._app_leaves()
                with store._leaf_conn(conn) as leaf:
                    session, session_token = leaves["identity"].verify_magic_link(leaf, business, token)
                    user_record = leaves["identity"].get_app_user(
                        leaf,
                        business,
                        app_user_id=session.app_user_id,
                    )
                    if user_record is None:
                        raise TakyonError("magic link user is missing")
                    existing_free = any(
                        ent.source == "manual" and ent.tier == "free"
                        for ent in leaves["entitlements"].list_entitlements(
                            leaf,
                            business,
                            app_user_id=user_record.id,
                        )
                    )
                    if not existing_free:
                        leaves["entitlements"].grant_entitlement(
                            leaf,
                            business,
                            app_user_id=user_record.id,
                            tier="free",
                            status="active",
                            source="manual",
                            metadata={"source": "magic_link"},
                        )
                    refreshed = leaves["identity"].get_app_user(
                        leaf,
                        business,
                        app_user_id=user_record.id,
                    )
                    leaves["profiles"].ensure_profile(
                        leaf,
                        business,
                        app_user_id=user_record.id,
                        display_name=user_record.name,
                    )
                if refreshed is None:
                    raise TakyonError("magic link user is missing")
                user = {
                    "id": refreshed.id,
                    "email": refreshed.email,
                    "status": refreshed.status,
                }
                tier = refreshed.tier
                session_id = session.id
                expires_at = str(session.expires_at)
            else:
                link = store._row_to_dict(conn.execute(
                    "SELECT * FROM app_magic_links WHERE business_slug = ? AND token_hash = ? AND used_at IS NULL AND expires_at > ? LIMIT 1",
                    (business, _hash_token(token), _now()),
                ).fetchone())
                if not link:
                    raise TakyonError("magic link is invalid, expired, or already used")
                user = store._row_to_dict(conn.execute("SELECT * FROM app_users WHERE business_slug = ? AND id = ?", (business, link["app_user_id"])).fetchone())
                if not user:
                    raise TakyonError("magic link user is missing")
                if _app_user_is_service_identity(user):
                    raise TakyonError("magic link is invalid, expired, or already used")
                if str(user.get("status") or "active") != "active":
                    raise TakyonError("app user is not active")
                now = _now()
                conn.execute("UPDATE app_magic_links SET used_at = ? WHERE id = ?", (now, link["id"]))
                existing_free = conn.execute(
                    "SELECT 1 FROM app_entitlements WHERE business_slug = ? AND app_user_id = ? AND source = 'manual' AND tier = 'free' LIMIT 1",
                    (business, user["id"]),
                ).fetchone()
                if not existing_free:
                    conn.execute(
                        "INSERT INTO app_entitlements (id, business_slug, app_user_id, tier, status, source, metadata_json, created_at, updated_at) VALUES (?, ?, ?, 'free', 'active', 'manual', ?, ?, ?)",
                        (uuid.uuid4().hex, business, user["id"], _json_dumps({"source": "magic_link"}), now, now),
                    )
                session_token = _random_token()
                session_id = uuid.uuid4().hex
                conn.execute(
                    "INSERT INTO app_sessions (id, business_slug, app_user_id, token_hash, expires_at, created_at) VALUES (?, ?, ?, ?, ?, ?)",
                    (session_id, business, user["id"], _hash_token(session_token), _future(days=30), now),
                )
                tier = store._sync_user_tier(conn, business, user["id"])
                _ensure_sqlite_app_profile(
                    conn,
                    business,
                    str(user["id"]),
                    display_name=user.get("name"),
                )
                expires_at = _future(days=30)
            store._record_event(conn, scope=f"business:{business}/app", business_slug=business, event_type="app.magic_link.verify", payload={"app_user_id": user["id"], "session_id": session_id})
            store._rewrite_app_files(conn, business)
        return tool_result({"success": True, "business": business, "app_user_id": user["id"], "email": user["email"], "tier": tier, "session_id": session_id, "session_token": session_token, "expires_at": expires_at})
    except Exception as exc:
        return tool_error(str(exc), success=False)


def handle_business_read_app_account(args: dict, **_: Any) -> str:
    store = _store()
    try:
        business = _slugify(str(args.get("business") or ""))
        with store._connect() as conn:
            store._ensure_business(conn, business)
            user = None
            if args.get("session_token"):
                user = store._row_to_dict(conn.execute(
                    "SELECT u.* FROM app_sessions s JOIN app_users u ON u.id = s.app_user_id WHERE s.business_slug = ? AND s.token_hash = ? AND s.revoked_at IS NULL AND s.expires_at > ? AND u.status = 'active' LIMIT 1",
                    (business, _hash_token(str(args.get("session_token"))), _now()),
                ).fetchone())
            elif args.get("app_user_id"):
                user = store._row_to_dict(conn.execute("SELECT * FROM app_users WHERE business_slug = ? AND id = ?", (business, str(args.get("app_user_id")))).fetchone())
            elif args.get("email"):
                user = store._row_to_dict(conn.execute("SELECT * FROM app_users WHERE business_slug = ? AND email = ?", (business, _normalize_email(str(args.get("email"))))).fetchone())
            if not user:
                raise TakyonError("app account not found")
            _maybe_reconcile_pg_completed_checkout(store, conn, business, user)
            user = store._row_to_dict(conn.execute("SELECT * FROM app_users WHERE business_slug = ? AND id = ?", (business, user["id"])).fetchone()) or user
            entitlements = [store._row_to_dict(row) for row in conn.execute("SELECT * FROM app_entitlements WHERE business_slug = ? AND app_user_id = ? ORDER BY updated_at DESC", (business, user["id"])).fetchall()]
            for entitlement in entitlements:
                metadata = entitlement.get("metadata") if isinstance(entitlement.get("metadata"), dict) else {}
                if "cancel_at_period_end" not in entitlement and "cancel_at_period_end" in metadata:
                    entitlement["cancel_at_period_end"] = bool(metadata.get("cancel_at_period_end"))
                if "stripe_subscription_status" not in entitlement and "stripe_subscription_status" in metadata:
                    entitlement["stripe_subscription_status"] = metadata.get("stripe_subscription_status")
            budget = store._ensure_app_budget(conn, business)
            usage = conn.execute(
                "SELECT COUNT(*) AS count, COALESCE(SUM(estimated_cost_microusd), 0) AS estimated, COALESCE(SUM(actual_cost_microusd), 0) AS actual FROM app_usage_events WHERE business_slug = ? AND app_user_id = ? AND created_at >= ?",
                (business, user["id"], budget["current_period_start"]),
            ).fetchone()
            revenue = conn.execute("SELECT COALESCE(SUM(amount_paid_cents), 0) AS cents, COUNT(*) AS count FROM app_revenue_events WHERE business_slug = ? AND lower(customer_email) = lower(?)", (business, user["email"])).fetchone()
        return tool_result({"success": True, "business": business, "user": user, "entitlements": entitlements, "usage_this_period": {"events": int(usage["count"] or 0), "estimated_cost_microusd": int(usage["estimated"] or 0), "actual_cost_microusd": int(usage["actual"] or 0)}, "revenue": {"events": int(revenue["count"] or 0), "amount_paid_cents": int(revenue["cents"] or 0)}})
    except Exception as exc:
        return tool_error(str(exc), success=False)


def handle_business_cancel_app_subscription(args: dict, **_: Any) -> str:
    store = _store()
    try:
        business = _resolved_business_slug(args, required=True)
        session_token = str(args.get("session_token") or "").strip()
        if not session_token:
            raise TakyonError("session_token is required")
        with store._connect() as conn:
            store._ensure_business(conn, business)
            if not isinstance(conn, _PGConn):
                raise TakyonError("app subscription cancellation requires the Postgres runtime")
            leaves = store._app_leaves()
            with store._leaf_conn(conn) as leaf:
                user = leaves["identity"].validate_session(leaf, business, session_token)
                if user is None:
                    raise TakyonError("app account not found")
            try:
                from . import stripe_util
            except ImportError:  # pragma: no cover - alternate load path when run as a top-level package
                from plugins.takyon import stripe_util
            try:
                with store._leaf_conn(conn) as leaf:
                    outcome = leaves["payments"].cancel_subscription(
                        leaf,
                        business,
                        app_user_id=user.id,
                        subscription_updater=lambda subscription_id, cancel_at_period_end: stripe_util.stripe_request(
                            f"subscriptions/{subscription_id}",
                            {
                                "cancel_at_period_end": (
                                    "true" if cancel_at_period_end else "false"
                                ),
                            },
                        ),
                    )
            except leaves["payments"].AppPaymentError as exc:
                raise TakyonError(str(exc)) from exc
            store._record_event(
                conn,
                scope=f"business:{business}/app",
                business_slug=business,
                event_type="app.subscription.cancel",
                payload={
                    "app_user_id": user.id,
                    "stripe_subscription_id": outcome.get("stripe_subscription_id"),
                    "cancel_at_period_end": bool(outcome.get("cancel_at_period_end")),
                    "already_canceling": bool(outcome.get("already_canceling")),
                },
            )
            store._rewrite_app_files(conn, business)
        return tool_result(
            {
                "success": True,
                "business": business,
                **outcome,
            }
        )
    except Exception as exc:
        return tool_error(str(exc), success=False)


def _maybe_reconcile_pg_completed_checkout(
    store: "TakyonStore",
    conn: sqlite3.Connection,
    business: str,
    user: Mapping[str, Any],
) -> dict[str, Any] | None:
    if not isinstance(conn, _PGConn):
        return None
    user_id = str(user.get("id") or "").strip()
    user_email = _normalize_email(str(user.get("email") or "")) if user.get("email") else ""
    if not user_id and not user_email:
        return None
    entitled = conn.execute(
        "SELECT 1 FROM app_entitlements "
        "WHERE business_slug = ? AND app_user_id = ? AND status IN ('active', 'trialing') "
        "AND (tier IN ('paid', 'pro', 'trial') OR plan_key IS NOT NULL "
        "OR stripe_subscription_id IS NOT NULL OR stripe_checkout_session_id IS NOT NULL) "
        "LIMIT 1",
        (business, user_id),
    ).fetchone()
    if entitled:
        return {"attempted": False, "reason": "already_entitled"}
    pending_rows = conn.execute(
        "SELECT stripe_checkout_session_id FROM app_checkout_intents "
        "WHERE business_slug = ? AND stripe_checkout_session_id IS NOT NULL "
        "AND status IN ('created', 'pending') "
        "AND ((? <> '' AND app_user_id = ?) OR (? <> '' AND lower(customer_email) = lower(?))) "
        "ORDER BY updated_at DESC LIMIT 3",
        (business, user_id, user_id, user_email, user_email),
    ).fetchall()
    if not pending_rows:
        return {"attempted": False, "reason": "no_pending_checkout"}
    try:
        from . import stripe_util
    except ImportError:  # pragma: no cover - alternate load path when run as a top-level package
        from plugins.takyon import stripe_util
    leaves = store._app_leaves()
    last_error = ""
    for row in pending_rows:
        session_id = str(row["stripe_checkout_session_id"] or "").strip()
        if not session_id:
            continue
        try:
            session = stripe_util.stripe_request(f"checkout/sessions/{session_id}", {}, method="GET")
            if not isinstance(session, dict):
                continue
            if str(session.get("status") or "").strip().lower() != "complete":
                continue
            with store._leaf_conn(conn) as leaf:
                checkout_result = leaves["payments"].reconcile_checkout_session(
                    leaf,
                    session,
                    event_created=session.get("created"),
                )
            subscription_result = None
            subscription_id = _stripe_object_id(session.get("subscription"))
            if subscription_id:
                subscription = stripe_util.stripe_request(
                    f"subscriptions/{subscription_id}",
                    {},
                    method="GET",
                )
                if isinstance(subscription, dict):
                    with store._leaf_conn(conn) as leaf:
                        subscription_result = leaves["payments"].reconcile_subscription(
                            leaf,
                            subscription,
                        )
            if checkout_result.get("recorded"):
                return {
                    "attempted": True,
                    "session_id": session_id,
                    "checkout": checkout_result,
                    "subscription": subscription_result,
                }
        except (stripe_util.StripeError, leaves["payments"].AppPaymentError, ValueError) as exc:
            last_error = str(exc)
    return {"attempted": True, "error": last_error or "checkout_not_reconciled"}


def handle_business_read_app_profile(args: dict, **_: Any) -> str:
    store = _store()
    try:
        business = _resolved_business_slug(args, required=True)
        with store._connect() as conn:
            store._ensure_business(conn, business)
            if isinstance(conn, _PGConn):
                leaves = store._app_leaves()
                try:
                    with store._leaf_conn(conn) as leaf:
                        resolved = leaves["profiles"].get_profile(
                            leaf,
                            business,
                            app_user_id=(str(args.get("app_user_id")) if args.get("app_user_id") else None),
                            email=(str(args.get("email")) if args.get("email") else None),
                            session_token=(str(args.get("session_token")) if args.get("session_token") else None),
                        )
                except (leaves["profiles"].AppProfileError, leaves["identity"].AppIdentityError, ValueError) as exc:
                    raise TakyonError(str(exc)) from exc
                if resolved is None:
                    raise TakyonError("app profile not found")
                if _is_service_email(resolved.user.email):
                    raise TakyonError("service identities have no profile")
                if resolved.profile is None:
                    with store._leaf_conn(conn) as leaf:
                        resolved = leaves["profiles"].ensure_profile(
                            leaf,
                            business,
                            app_user_id=resolved.user.id,
                            display_name=resolved.user.name,
                        )
                user_payload = _app_user_runtime_payload(resolved.user)
                profile_payload = _app_profile_runtime_payload(resolved.profile)
                exists = profile_payload is not None
            else:
                user = None
                if args.get("session_token"):
                    user = store._row_to_dict(conn.execute(
                        "SELECT u.* FROM app_sessions s JOIN app_users u ON u.id = s.app_user_id "
                        "WHERE s.business_slug = ? AND s.token_hash = ? AND s.revoked_at IS NULL "
                        "AND s.expires_at > ? AND u.status = 'active' LIMIT 1",
                        (business, _hash_token(str(args.get("session_token"))), _now()),
                    ).fetchone())
                elif args.get("app_user_id"):
                    user = store._row_to_dict(conn.execute(
                        "SELECT * FROM app_users WHERE business_slug = ? AND id = ?",
                        (business, str(args.get("app_user_id"))),
                    ).fetchone())
                elif args.get("email"):
                    user = store._row_to_dict(conn.execute(
                        "SELECT * FROM app_users WHERE business_slug = ? AND email = ?",
                        (business, _normalize_email(str(args.get("email")))),
                    ).fetchone())
                else:
                    raise TakyonError("app profile read requires session_token, app_user_id, or email")
                if not user:
                    raise TakyonError("app profile not found")
                if _app_user_is_service_identity(user):
                    raise TakyonError("service identities have no profile")
                profile = _ensure_sqlite_app_profile(
                    conn,
                    business,
                    str(user["id"]),
                    display_name=user.get("name"),
                )
                user_payload = _app_user_runtime_payload(user)
                if profile:
                    profile_payload = {
                        "id": str(profile["id"]),
                        "business_slug": business,
                        "app_user_id": str(profile["id"]),
                        "display_name": profile.get("display_name"),
                        "headline": profile.get("headline"),
                        "bio": str(profile.get("bio") or ""),
                        "attributes": _json_loads(profile.get("attributes_json"), {}),
                        "metadata": _json_loads(profile.get("metadata_json"), {}),
                        "created_at": str(profile.get("created_at") or ""),
                        "updated_at": str(profile.get("updated_at") or ""),
                    }
                else:
                    profile_payload = None
                exists = profile_payload is not None
        return tool_result({
            "success": True,
            "business": business,
            "exists": exists,
            "user": user_payload,
            "profile": profile_payload,
        })
    except Exception as exc:
        return tool_error(str(exc), success=False)


def handle_business_list_app_directory_entries(args: dict, **_: Any) -> str:
    store = _store()
    try:
        business = _resolved_business_slug(args, required=True)
        limit = _clamp_int(args.get("limit"), default=50, minimum=1, maximum=100)
        include_disabled = bool(args.get("include_disabled") or args.get("includeDisabled"))
        viewer_mode = bool(args.get("session_token") or args.get("app_user_id") or args.get("email"))
        with store._connect() as conn:
            store._ensure_business(conn, business)
            if viewer_mode:
                if isinstance(conn, _PGConn):
                    leaves = store._app_leaves()
                    try:
                        with store._leaf_conn(conn) as leaf:
                            resolved = leaves["directory"].list_visible_entries(
                                leaf,
                                business,
                                app_user_id=(str(args.get("app_user_id")) if args.get("app_user_id") else None),
                                email=(str(args.get("email")) if args.get("email") else None),
                                session_token=(str(args.get("session_token")) if args.get("session_token") else None),
                                limit=limit,
                            )
                    except (leaves["directory"].AppDirectoryError, leaves["identity"].AppIdentityError, ValueError) as exc:
                        raise TakyonError(str(exc)) from exc
                    if resolved is None:
                        raise TakyonError("app account not found")
                    viewer, entries = resolved
                    viewer_payload = _app_user_runtime_payload(viewer)
                    entry_payloads = [_app_directory_entry_runtime_payload(item.entry) for item in entries]
                    return tool_result(
                        {
                            "success": True,
                            "business": business,
                            "viewer": viewer_payload,
                            "count": len(entry_payloads),
                            "entries": entry_payloads,
                        }
                    )
                viewer = _resolve_sqlite_app_user(
                    conn,
                    business,
                    session_token=args.get("session_token"),
                    app_user_id=args.get("app_user_id"),
                    email=args.get("email"),
                )
                if not viewer:
                    raise TakyonError("app account not found")
                rows = conn.execute(
                    "SELECT p.* FROM app_user_profiles p "
                    "JOIN app_users u ON u.business_slug = p.business_slug AND u.id = p.id "
                    "WHERE p.business_slug = ? "
                    "  AND COALESCE(p.directory_enabled, 0) = 1 "
                    "  AND u.status = 'active' "
                    "  AND p.id <> ? "
                    "  AND NOT EXISTS ("
                    "    SELECT 1 FROM app_connections c "
                    "    WHERE c.business_slug = p.business_slug "
                    "      AND c.state = 'block' "
                    "      AND ("
                    "        (c.source_app_user_id = ? AND c.target_app_user_id = p.id) "
                    "        OR (c.source_app_user_id = p.id AND c.target_app_user_id = ?)"
                    "      )"
                    "  ) "
                    "ORDER BY COALESCE(p.directory_updated_at, p.updated_at) DESC, p.id ASC LIMIT ?",
                    (business, str(viewer["id"]), str(viewer["id"]), str(viewer["id"]), limit),
                ).fetchall()
                entry_payloads = [_app_directory_entry_runtime_payload(store._row_to_dict(row)) for row in rows]
                return tool_result(
                    {
                        "success": True,
                        "business": business,
                        "viewer": _app_user_runtime_payload(viewer),
                        "count": len(entry_payloads),
                        "entries": entry_payloads,
                    }
                )
            if isinstance(conn, _PGConn):
                leaves = store._app_leaves()
                try:
                    with store._leaf_conn(conn) as leaf:
                        entries = leaves["directory"].list_admin_entries(
                            leaf,
                            business,
                            include_disabled=include_disabled,
                            limit=limit,
                        )
                except (leaves["directory"].AppDirectoryError, ValueError) as exc:
                    raise TakyonError(str(exc)) from exc
                payloads = [
                    {
                        "user": _app_user_runtime_payload(item.user),
                        "directory_entry": _app_directory_entry_runtime_payload(item.entry),
                    }
                    for item in entries
                ]
            else:
                rows = conn.execute(
                    "SELECT u.*, p.directory_enabled, p.directory_profile_json, p.created_at AS profile_created_at, "
                    "COALESCE(p.directory_updated_at, p.updated_at, u.updated_at) AS profile_updated_at "
                    "FROM app_users u "
                    "LEFT JOIN app_user_profiles p ON p.business_slug = u.business_slug AND p.id = u.id "
                    "WHERE u.business_slug = ? "
                    + ("" if include_disabled else "AND COALESCE(p.directory_enabled, 0) = 1 ")
                    + "ORDER BY COALESCE(p.directory_updated_at, p.updated_at, u.updated_at) DESC, u.id ASC LIMIT ?",
                    (business, limit),
                ).fetchall()
                payloads = []
                for row in rows:
                    row_dict = store._row_to_dict(row)
                    payloads.append(
                        {
                            "user": _app_user_runtime_payload(
                                {
                                    "id": row_dict.get("id"),
                                    "business_slug": row_dict.get("business_slug"),
                                    "email": row_dict.get("email"),
                                    "name": row_dict.get("name"),
                                    "status": row_dict.get("status"),
                                    "tier": row_dict.get("tier"),
                                }
                            ),
                            "directory_entry": _app_directory_entry_runtime_payload(
                                {
                                    "app_user_id": row_dict.get("id"),
                                    "business_slug": row_dict.get("business_slug"),
                                    "directory_enabled": row_dict.get("directory_enabled"),
                                    "directory_profile_json": row_dict.get("directory_profile_json"),
                                    "created_at": row_dict.get("profile_created_at") or row_dict.get("created_at"),
                                    "directory_updated_at": row_dict.get("profile_updated_at"),
                                }
                            ),
                        }
                    )
        return tool_result({"success": True, "business": business, "count": len(payloads), "entries": payloads})
    except Exception as exc:
        return tool_error(str(exc), success=False)


def handle_business_read_app_directory_entry(args: dict, **_: Any) -> str:
    store = _store()
    try:
        business = _resolved_business_slug(args, required=True)
        target_app_user_id = str(args.get("app_user_id") or "").strip()
        target_email = str(args.get("email") or "").strip()
        session_token = str(args.get("session_token") or "").strip()
        with store._connect() as conn:
            store._ensure_business(conn, business)
            if session_token:
                if isinstance(conn, _PGConn):
                    leaves = store._app_leaves()
                    try:
                        with store._leaf_conn(conn) as leaf:
                            if target_app_user_id or target_email:
                                target_id = target_app_user_id
                                if not target_id and target_email:
                                    target_user = leaves["identity"].get_app_user(
                                        leaf,
                                        business,
                                        email=target_email,
                                    )
                                    target_id = target_user.id if target_user is not None else ""
                                resolved = leaves["directory"].get_visible_entry(
                                    leaf,
                                    business,
                                    target_app_user_id=target_id,
                                    session_token=session_token,
                                )
                            else:
                                self_entry = leaves["directory"].get_self_entry(
                                    leaf,
                                    business,
                                    session_token=session_token,
                                )
                                if self_entry is None:
                                    raise TakyonError("app account not found")
                                return tool_result(
                                    {
                                        "success": True,
                                        "business": business,
                                        "user": _app_user_runtime_payload(self_entry.user),
                                        "directory_entry": _app_directory_entry_runtime_payload(self_entry.entry),
                                    }
                                )
                    except (leaves["directory"].AppDirectoryError, leaves["identity"].AppIdentityError, ValueError) as exc:
                        raise TakyonError(str(exc)) from exc
                    if resolved is None:
                        raise TakyonError("app directory entry not found")
                    viewer, entry = resolved
                    return tool_result(
                        {
                            "success": True,
                            "business": business,
                            "viewer": _app_user_runtime_payload(viewer),
                            "directory_entry": _app_directory_entry_runtime_payload(entry.entry),
                        }
                    )
                viewer = _resolve_sqlite_app_user(conn, business, session_token=session_token)
                if not viewer:
                    raise TakyonError("app account not found")
                if not target_app_user_id and not target_email:
                    existing = _ensure_sqlite_app_profile(
                        conn,
                        business,
                        str(viewer["id"]),
                        display_name=viewer.get("name"),
                    )
                    return tool_result(
                        {
                            "success": True,
                            "business": business,
                            "user": _app_user_runtime_payload(viewer),
                            "directory_entry": _app_directory_entry_runtime_payload(existing),
                        }
                    )
                target_id = target_app_user_id
                if not target_id and target_email:
                    target_user = _resolve_sqlite_app_user(conn, business, email=target_email)
                    target_id = str(target_user["id"]) if target_user else ""
                entry_payload = _sqlite_directory_entry_for_viewer(
                    conn,
                    business,
                    viewer_app_user_id=str(viewer["id"]),
                    target_app_user_id=target_id,
                )
                if entry_payload is None:
                    raise TakyonError("app directory entry not found")
                return tool_result(
                    {
                        "success": True,
                        "business": business,
                        "viewer": _app_user_runtime_payload(viewer),
                        "directory_entry": entry_payload,
                    }
                )

            if isinstance(conn, _PGConn):
                leaves = store._app_leaves()
                try:
                    with store._leaf_conn(conn) as leaf:
                        resolved = leaves["directory"].read_admin_entry(
                            leaf,
                            business,
                            app_user_id=(target_app_user_id or None),
                            email=(target_email or None),
                        )
                except (leaves["directory"].AppDirectoryError, ValueError) as exc:
                    raise TakyonError(str(exc)) from exc
                if resolved is None:
                    raise TakyonError("app directory entry not found")
                return tool_result(
                    {
                        "success": True,
                        "business": business,
                        "user": _app_user_runtime_payload(resolved.user),
                        "directory_entry": _app_directory_entry_runtime_payload(resolved.entry),
                    }
                )
            user = _resolve_sqlite_app_user(
                conn,
                business,
                app_user_id=(target_app_user_id or None),
                email=(target_email or None),
            )
            if not user:
                raise TakyonError("app directory entry not found")
            profile_row = conn.execute(
                "SELECT * FROM app_user_profiles WHERE business_slug = ? AND id = ?",
                (business, str(user["id"])),
            ).fetchone()
            return tool_result(
                {
                    "success": True,
                    "business": business,
                    "user": _app_user_runtime_payload(user),
                    "directory_entry": _app_directory_entry_runtime_payload(
                        store._row_to_dict(profile_row)
                        if profile_row is not None
                        else {
                            "app_user_id": user.get("id"),
                            "business_slug": user.get("business_slug"),
                            "directory_enabled": False,
                            "directory_profile_json": _json_dumps({}),
                            "created_at": "",
                            "directory_updated_at": "",
                        }
                    ),
                }
            )
    except Exception as exc:
        return tool_error(str(exc), success=False)


